"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["10583"],{11763(e){e.exports=JSON.parse('{"id":"FIN-990","slug":"law-of-large-numbers","term":"Law of Large Numbers","also_known_as":[],"difficulty":"Intermediate","definition":"The law of large numbers is a principle of probability stating that as the number of trials or observations increases, the average of the results gets closer to the expected value.","explanation":["With just a few observations, results can vary widely by chance. With many observations, random variations tend to cancel out, and the average becomes more predictable.","For example, if you toss a fair coin ten times, you might get seven heads, a 70% rate. If you toss it 10,000 times, the proportion of heads will almost certainly be very close to 50%.","The law of large numbers is the foundation of insurance. An insurer cannot predict whether any individual home will catch fire, but across hundreds of thousands of policies, it can predict fairly accurately how many claims it will receive. This allows it to set premiums that cover expected claims and costs. The same principle helps lenders estimate default rates across large portfolios of loans and casinos rely on it to make steady profits.","The law of large numbers does not mean that results balance out in the short run. Believing that a run of losses makes a win more likely is a mistake known as the gambler\'s fallacy. Each independent event, such as a coin toss, has the same probability regardless of what happened before."],"note":"","total":1500,"prev":{"slug":"late-fee","term":"Late Fee"},"next":{"slug":"leading-indicator","term":"Leading Indicator"}}')}}]);